@if($canManage)<div class="grid gap-4 lg:grid-cols-2">@if($project->status==='draft'&&!$hasBaseline)<x-ui.panel><h2 class="mb-4 font-bold text-blue-900">إضافة مرحلة</h2><form wire:submit="addPhase" class="space-y-3"><flux:input label="اسم المرحلة" wire:model="phase.title"/><flux:input type="date" label="البداية" wire:model="phase.start_date"/><flux:input type="date" label="النهاية" wire:model="phase.end_date"/><flux:button type="submit" icon="plus">إضافة مرحلة</flux:button></form></x-ui.panel>@endif<x-ui.panel><h2 class="mb-4 font-bold text-blue-900">إضافة مهمة</h2><form wire:submit="addTask" class="grid gap-3 sm:grid-cols-2"><flux:input label="المهمة" wire:model="task.title"/><flux:select label="المرحلة" wire:model="task.phase_id"><option value="">اختر المرحلة</option>@foreach($progress['phases'] as $p)<option value="{{ $p->id }}">{{ $p->title }}</option>@endforeach</flux:select><flux:select label="المكلف" wire:model="task.assigned_to"><option value="">اختر عضو الفريق</option>@foreach($users as $u)@if($u['id']==$project->manager_id||in_array($u['id'],$form['members']))<option value="{{ $u['id'] }}">{{ $u['name'] }}</option>@endif @endforeach</flux:select><flux:input type="date" label="البداية" wire:model="task.start_date"/><flux:input type="date" label="النهاية" wire:model="task.end_date"/><flux:input label="وصف وملاحظات" wire:model="task.notes"/><flux:select label="أولوية المهمة" wire:model="task.priority"><option value="low">منخفضة</option><option value="normal">عادية</option><option value="high">عالية</option><option value="urgent">عاجلة</option></flux:select><flux:checkbox label="مطلوبة للإكمال" wire:model="task.required"/><flux:button type="submit" icon="plus">{{ $editingTask?'حفظ تعديل المهمة':'إضافة مهمة' }}</flux:button></form></x-ui.panel></div>@endif
